const vocab = $('Baixar vocabulario').first().json.data;
const meta = $('Montar prompt').first().json;

const bruto = $input.first().json;

let dados = null;
if (bruto.output && bruto.output[0] && bruto.output[0].content && bruto.output[0].content[0]) {
  dados = bruto.output[0].content[0].text;
}
if (!dados) dados = bruto.content || bruto.output_text || bruto.text || bruto;

if (typeof dados === 'string') {
  const ini = dados.indexOf('{');
  const fim = dados.lastIndexOf('}');
  dados = JSON.parse(dados.slice(ini, fim + 1));
}

const lista = dados.ejercicios || dados.exercicios || dados;
if (!Array.isArray(lista)) {
  throw new Error('Nao achei a lista de exercicios. Chaves recebidas: ' + Object.keys(dados).join(', '));
}

function norm(s) {
  return String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9n ]/g, ' ');
}

const conhecidas = new Set();
const todas = norm(vocab).split(/\s+/);
for (let i = 0; i < todas.length; i++) {
  if (todas[i].length > 2) conhecidas.add(todas[i]);
}
const basicas = 'hola gracias favor por si no adios buenos buenas dias tardes noches uno dos tres cuatro cinco seis siete ocho nueve diez once doce trece catorce quince veinte treinta cien rojo azul verde amarillo blanco negro padre madre hermano hermana hijo hija escucha habla lectura vocabulario responde preguntas escribe frase palabra audio segundos'.split(' ');
for (let i = 0; i < basicas.length; i++) conhecidas.add(basicas[i]);

const contador = {};
const saida = [];
for (let k = 0; k < lista.length; k++) {
  const e = lista[k];
  const dia = e.dia || 'sem';
  contador[dia] = (contador[dia] || 0) + 1;
  const id = meta.semana + '-' + dia + '-' + contador[dia];

  const partes = [e.enunciado, e.guion, e.opcao_a, e.opcao_b, e.opcao_c, e.opcao_d];
  const campos = partes.filter(function (x) { return x; }).join(' ');
  const novas = [];
  const palavras = norm(campos).split(/\s+/);
  for (let j = 0; j < palavras.length; j++) {
    const p = palavras[j];
    if (p.length > 4 && !conhecidas.has(p) && novas.indexOf(p) === -1) novas.push(p);
  }
  saida.push({ json: {
    id: id,
    semana: meta.semana,
    dia: dia,
    tipo: e.tipo || '',
    fonte: meta.fonte,
    enunciado: e.enunciado || '',
    guion: e.guion || '',
    opcao_a: e.opcao_a || '',
    opcao_b: e.opcao_b || '',
    opcao_c: e.opcao_c || '',
    opcao_d: e.opcao_d || '',
    gabarito: e.gabarito || '',
    explicacao: e.explicacao || e.explicacion || '',
    palabras_nuevas: novas.join(', '),
    status: novas.length > 12 ? 'revisar' : 'rascunho',
    enviado_em: ''
  } });
}
return saida;
